__NUXT_JSONP__("/de/price", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{details:{slug:b,pageTitle:"Preise | Mentor Language Institute",pageDescription:"Wenn du dir selbst eine Unterkunft suchst, musst du keine ②Unterkunftskosten bei uns zahlen.",title:"Preise",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fde\u002Fprice-auto\"\u003EPreiskalkulator\u003C\u002Fa\u003E"]}]},steps:{title:"①Studiengebühr ＋ ②Unterkunftskosten ＋ ③Andere Gebühren",subtitle:["Wenn du dir selbst eine Unterkunft suchst, musst du keine ②Unterkunftskosten bei uns zahlen.\u003Cbr\u003E\u003Ca href=\"\u002Fde\u002Fprice-auto\u002F\"\u003E*Bitte verwende den Preiskalkulator um ein Angebot zu erhalten.\u003C\u002Fa\u003E"],lists:[{title:"①Studiengebühr",subtitle:["Der Preis variiert anhand deines gewählten Kurses und der Länge deines Aufenthalts.\u003Cbr \u002F\u003E Je länger du am MLI studierst, desto grösser ist dein Rabatt."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",description:["\u003Cb\u003EF&A\u003C\u002Fb\u003E","\u003Cb\u003EF1: Kann ich die Gebühren mit Kreditkarte bezahlen? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003EA1:\u003C\u002Fb\u003E Ja, Sie können Ihre Gebühren mit Kreditkarte bezahlen. Es wird jedoch eine Servicegebühr von 4 % hinzugefügt.","\u003Cb\u003EF2: Welche Zahlungsmethoden kann ich verwenden, um MLI zu bezahlen?\u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA2:\u003C\u002Fb\u003E Wir akzeptieren folgende Zahlungsmethoden: \u003Cbr\u003E • Banküberweisung \u003Cbr\u003E • Internationale Überweisung \u003Cbr\u003E • Bargeld \u003Cbr\u003E • Persönlicher Scheck \u003Cbr\u003E • Kreditkarte \u003Cbr\u003E • Debitkarte \u003Cbr\u003E • Zelle","Wenn Sie die 4% Servicegebühr für Kredit-\u002FDebitkartenzahlungen vermeiden möchten, können Sie eine der folgenden Alternativen wählen: \u003Cbr\u003E\u003Cb\u003EBanküberweisung, internationale Überweisung (es fällt eine Bankgebühr von 35 USD an), Barzahlung, persönlicher Scheck oder Zelle.\u003C\u002Fb\u003E","\u003Cb\u003EF3: Kann ich die Studiengebühren nach Beginn meines Programms zahlen? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003EA3:\u003C\u002Fb\u003E Nein. Die vollständige Zahlung muss vor oder am ersten Programmtag erfolgen."]},{title:"②Unterkunftskosten",subtitle:["Wir bieten Gastfamilien- und Studentenheimoptionen an. Gastfamilien sind empfehlenswert für Leute, welche die amerikanische Kultur erleben möchten. Studentenwohnheime werden für Leute empfohlen, die viele Freunde machen möchten."],category:[{title:"Gastfamilienpreise",table:{tableMaxCol:3,title:"Platzierungsgebühr* : $300\u003Cbr \u002F\u003E Wenn Sie jünger als 18 Jahre alt sind, liegt die Miete etwa 10 % über dem Preis für eine Person, die älter als 18 Jahre ist.",thead:[c,d,"Zweierzimmer***"],tbody:[["\u003Cb\u003EKaution**\u003C\u002Fb\u003E",a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]}},{title:"Studentenwohnheimpreise",table:{tableMaxCol:4,title:"Platzierungsgebühr* : $200\u003Cbr \u002F\u003E Wenn Sie jünger als 18 Jahre alt sind, liegt die Miete etwa 10 % über dem Preis für eine Person, die älter als 18 Jahre ist.",thead:[c,d,"Zweierzimmer","Viererzimmer"],tbody:[["\u003Cb\u003E Kaution**\u003C\u002Fb\u003E",a,a,a],[e,"$570","$430","$315"],[f,"$1,140","$860","$630"],[g,"$1,710","$1,290","$945"],[h,"$2,280","$1,720","$1,260"],[i,"$4,320","$3,080","$2,320"],[j,"$6,480","$4,620","$3,480"]]},description:["*Die Platzierungsgebühr ist eine Einmalzahlung. Sie wird nicht zurückerstattet.\u003Cbr \u002F\u003E**Die Kaution wird nach dem Auszug der Studenten zurückerstattet.\u003Cbr \u002F\u003E***Wenn du dich für ein geteiltes Zimmer in einer Gastfamilie bewirbst, musst du dich mit einer zweiten Person anmelden.","※Deine Unterkunft wird von U.S. Support Service Inc. oder anderen Partnern zu Verfügung gestellt.","\u003Ca href=\"\u002Fde\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E   Mehr Informationen über Unterkünfte\u003C\u002Fa\u003E"]}]},{title:"③Erstgebühren",subtitle:["Zusätzlich zu den oben genannten Gebühren, fallen weitere Erstgebühren an."],lists:["Bearbeitungsgebühr* ： $150","I-20 Postversand** : $120","SEVIS Gebühr** ： $350 (wird direkt an SEVP gezahlt)","Lehrbücher ： $150-240"],description:["*Nicht rückerstattbar\u003Cbr \u002F\u003E**Nur bei Beantragung eines Studentenvisums"]}]},examples:{title:"Beispiele",subtitle:["Kostenbeispiele: 1 Monat (4 Wochen) und 1 Jahr (48 Wochen)"],lists:[{title:"1 Monat (4 Wochen)",items:[k,"Studiengebühr : $1,220","Unterkunft : $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003ETotal : $3,000\u003C\u002Fspan\u003E"]},{title:"1 Jahr (48 Wochen)",items:[k,"Studiengebühr : $10,032","Unterkunft : $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway）","\u003Cspan class='total'\u003ETotal : $23,992\u003C\u002Fspan\u003E"]}]},other_info:["Solltest du Fragen zu den Gebühren haben, kannst du uns gerne kontaktieren."],dir:"\u002Fprice",path:"\u002Fprice\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:30.166Z",updatedAt:"2026-03-24T13:34:16.710Z"},lang:b}],fetch:{},mutations:void 0}}("$300","de","","Privatzimmer","1 Woche","2 Wochen","3 Wochen","4 Wochen","8 Wochen","12 Wochen","Erstgebühren : $150")));